window.UI_TPL="\n<div dir=\"rtl\" style=\"position:relative;width:100%;height:100vh;height:100dvh;box-sizing:border-box;display:flex;flex-direction:column;background:#F4F5F2;color:#1B2421;font-family:'IBM Plex Sans Arabic',system-ui,sans-serif;font-size:15px;overflow:hidden\">\n\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <symbol id=\"i-home\" viewBox=\"0 0 24 24\"><path d=\"M3 11l9-8 9 8v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1V11z\"/></symbol>\n  <symbol id=\"i-pot\" viewBox=\"0 0 24 24\"><path d=\"M4 10h16v6a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4v-6z M2 10h20 M8 6c0-1 .8-1.5.8-2.5 M12 6c0-1 .8-1.5.8-2.5 M16 6c0-1 .8-1.5.8-2.5\"/></symbol>\n  <symbol id=\"i-box\" viewBox=\"0 0 24 24\"><path d=\"M21 8l-9-5-9 5v8l9 5 9-5V8z M3.3 7.5L12 12.5l8.7-5 M12 22V12.5\"/></symbol>\n  <symbol id=\"i-users\" viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M22 21v-2a4 4 0 0 0-3-3.9 M16 3.1a4 4 0 0 1 0 7.8\"/></symbol>\n  <symbol id=\"i-menu\" viewBox=\"0 0 24 24\"><path d=\"M4 6h16 M4 12h16 M4 18h16\"/></symbol>\n  <symbol id=\"i-plus\" viewBox=\"0 0 24 24\"><path d=\"M12 5v14 M5 12h14\"/></symbol>\n  <symbol id=\"i-minus\" viewBox=\"0 0 24 24\"><path d=\"M5 12h14\"/></symbol>\n  <symbol id=\"i-check\" viewBox=\"0 0 24 24\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></symbol>\n  <symbol id=\"i-x\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12 M18 6L6 18\"/></symbol>\n  <symbol id=\"i-chevR\" viewBox=\"0 0 24 24\"><path d=\"M9 6l6 6-6 6\"/></symbol>\n  <symbol id=\"i-chevL\" viewBox=\"0 0 24 24\"><path d=\"M15 6l-6 6 6 6\"/></symbol>\n  <symbol id=\"i-chevD\" viewBox=\"0 0 24 24\"><path d=\"M6 9l6 6 6-6\"/></symbol>\n  <symbol id=\"i-alert\" viewBox=\"0 0 24 24\"><path d=\"M12 9v4 M12 17h.01 M10.3 3.9L2.4 18a2 2 0 0 0 1.7 3h15.8a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z\"/></symbol>\n  <symbol id=\"i-wifi\" viewBox=\"0 0 24 24\"><path d=\"M2 8.8a15 15 0 0 1 20 0 M5 12.9a10 10 0 0 1 14 0 M8.5 16.4a5 5 0 0 1 7 0 M12 20h.01\"/></symbol>\n  <symbol id=\"i-wifiOff\" viewBox=\"0 0 24 24\"><path d=\"M2 8.8a15 15 0 0 1 4.2-2.6 M5 12.9a10 10 0 0 1 5.2-2.7 M8.5 16.4a5 5 0 0 1 7 0 M12 20h.01 M2 2l20 20\"/></symbol>\n  <symbol id=\"i-doc\" viewBox=\"0 0 24 24\"><path d=\"M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8l-5-5z M14 3v5h5 M9 13h6 M9 17h6\"/></symbol>\n  <symbol id=\"i-wallet\" viewBox=\"0 0 24 24\"><path d=\"M3 7a2 2 0 0 1 2-2h13v4 M3 7v11a2 2 0 0 0 2 2h14a1 1 0 0 0 1-1v-9a1 1 0 0 0-1-1H5a2 2 0 0 1-2-2z M16 14.5h.01\"/></symbol>\n  <symbol id=\"i-truck\" viewBox=\"0 0 24 24\"><path d=\"M2 6h11v10H2z M13 9h4l4 4v3h-8 M6.5 19a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3z M17.5 19a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3z\"/></symbol>\n  <symbol id=\"i-search\" viewBox=\"0 0 24 24\"><path d=\"M11 18a7 7 0 1 0 0-14 7 7 0 0 0 0 14z M21 21l-4.3-4.3\"/></symbol>\n  <symbol id=\"i-heart\" viewBox=\"0 0 24 24\"><path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8l1 1.1L12 21l7.8-7.5 1-1.1a5.5 5.5 0 0 0 0-7.8z\"/></symbol>\n  <symbol id=\"i-userPlus\" viewBox=\"0 0 24 24\"><path d=\"M15 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M8.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M19 8v6 M16 11h6\"/></symbol>\n  <symbol id=\"i-book\" viewBox=\"0 0 24 24\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5v14z M4 19.5A2.5 2.5 0 0 0 6.5 22H20v-5\"/></symbol>\n  <symbol id=\"i-shield\" viewBox=\"0 0 24 24\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></symbol>\n  <symbol id=\"i-sliders\" viewBox=\"0 0 24 24\"><path d=\"M4 21v-7 M4 10V3 M12 21v-9 M12 8V3 M20 21v-5 M20 12V3 M1 14h6 M9 8h6 M17 16h6\"/></symbol>\n  <symbol id=\"i-calendar\" viewBox=\"0 0 24 24\"><path d=\"M5 4h14a2 2 0 0 1 2 2v13a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z M16 2v4 M8 2v4 M3 10h18\"/></symbol>\n  <symbol id=\"i-clock\" viewBox=\"0 0 24 24\"><path d=\"M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18z M12 7v5l3 2\"/></symbol>\n  <symbol id=\"i-pencil\" viewBox=\"0 0 24 24\"><path d=\"M12 20h9 M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z\"/></symbol>\n  <symbol id=\"i-send\" viewBox=\"0 0 24 24\"><path d=\"M22 2L11 13 M22 2l-7 20-4-9-9-4z\"/></symbol>\n  <symbol id=\"i-list\" viewBox=\"0 0 24 24\"><path d=\"M9 6h11 M9 12h11 M9 18h11 M4 6l1 1 2-2 M4 12l1 1 2-2 M4 18l1 1 2-2\"/></symbol>\n  <symbol id=\"i-copy\" viewBox=\"0 0 24 24\"><path d=\"M9 9h11v11H9z M5 15H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v1\"/></symbol>\n  <symbol id=\"i-lock\" viewBox=\"0 0 24 24\"><path d=\"M5 11h14v10H5z M8 11V7a4 4 0 0 1 8 0v4\"/></symbol>\n  <symbol id=\"i-camera\" viewBox=\"0 0 24 24\"><path d=\"M3 8a2 2 0 0 1 2-2h2.5l1.5-2h6l1.5 2H19a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><circle cx=\"12\" cy=\"13\" r=\"3.6\"/></symbol>\n  <symbol id=\"i-download\" viewBox=\"0 0 24 24\"><path d=\"M12 4v11 M7.5 11l4.5 4.5 4.5-4.5 M5 20h14\"/></symbol>\n  <symbol id=\"i-image\" viewBox=\"0 0 24 24\"><path d=\"M4 5h16v14H4z M4 16l5-5 4 4 3-3 4 4\"/><circle cx=\"9\" cy=\"9.5\" r=\"1.2\"/></symbol>\n  <symbol id=\"i-dot\" viewBox=\"0 0 24 24\"><path d=\"M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z\"/></symbol>\n</svg>\n\n<!-- الرأس -->\n<div style=\"flex:none;padding:14px 16px 8px;display:flex;align-items:center;gap:10px\">\n  <sc-if value=\"{{canBack}}\" hint-placeholder-val=\"{{false}}\">\n  <button onClick=\"{{goBack}}\" aria-label=\"رجوع\" style=\"flex:none;width:44px;height:44px;border-radius:14px;border:0;background:#fff;color:#1B2421;box-shadow:0 0 0 1px rgba(27,36,33,.1);display:flex;align-items:center;justify-content:center\">\n    <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-chevR\"></use></svg>\n  </button>\n  </sc-if>\n  <div style=\"flex:1;min-width:0\">\n    <h1 style=\"margin:0;font-size:22px;font-weight:600;line-height:1.3\">{{title}}</h1>\n    <sc-if value=\"{{hasSub}}\" hint-placeholder-val=\"{{true}}\"><div style=\"font-size:13px;color:#5B6660;margin-top:1px\">{{sub}}</div></sc-if>\n  </div>\n  <button onClick=\"{{searchGo}}\" aria-label=\"بحث\" style=\"flex:none;width:44px;height:44px;border-radius:14px;border:0;background:#fff;color:#1B2421;box-shadow:0 0 0 1px rgba(27,36,33,.1);display:flex;align-items:center;justify-content:center\">\n    <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-search\"></use></svg>\n  </button>\n  <sc-if value=\"{{hasAction}}\" hint-placeholder-val=\"{{false}}\">\n  <button onClick=\"{{actionGo}}\" style=\"flex:none;min-height:44px;padding:0 14px;border-radius:14px;border:0;background:#14563A;color:#fff;font-size:14px;font-weight:500;display:flex;align-items:center;gap:6px\">\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-plus\"></use></svg>\n    <span>{{actionLabel}}</span>\n  </button>\n  </sc-if>\n  <sc-if value=\"{{isMain}}\" hint-placeholder-val=\"{{true}}\">\n  <button onClick=\"{{toggleOffline}}\" aria-pressed=\"{{offline}}\" style=\"flex:none;min-height:44px;display:flex;align-items:center;gap:6px;border-radius:999px;border:0;padding:0 12px;font-size:12px;font-weight:500;background:{{pillBg}};color:{{pillFg}}\">\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#{{pillIcon}}\"></use></svg>\n    <span>{{pillText}}</span>\n  </button>\n  </sc-if>\n</div>\n\n<!-- المحتوى: كتل عامة -->\n<div style=\"flex:1;min-height:0;overflow-y:auto;padding:4px 16px 18px;display:flex;flex-direction:column;gap:14px\">\n<sc-for list=\"{{blocks}}\" as=\"b\" hint-placeholder-count=\"3\">\n\n  <!-- شهر التقويم -->\n  <sc-if value=\"{{b.isMonth}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"background:#fff;border-radius:16px;padding:10px 10px 12px;box-shadow:0 0 0 1px rgba(27,36,33,.07)\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:6px\">\n      <button onClick=\"{{b.mon.next}}\" aria-label=\"الشهر التالي\" style=\"width:44px;height:44px;border-radius:12px;border:1px solid rgba(27,36,33,.18);background:#fff;display:flex;align-items:center;justify-content:center\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#1B2421\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-chevL\"></use></svg></button>\n      <div style=\"font-size:16px;font-weight:600\">{{b.mon.title}}</div>\n      <button onClick=\"{{b.mon.prev}}\" aria-label=\"الشهر السابق\" style=\"width:44px;height:44px;border-radius:12px;border:1px solid rgba(27,36,33,.18);background:#fff;display:flex;align-items:center;justify-content:center\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#1B2421\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-chevR\"></use></svg></button>\n    </div>\n    <div style=\"display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center\">\n      <sc-for list=\"{{b.mon.head}}\" as=\"h\" hint-placeholder-count=\"7\"><div style=\"font-size:11.5px;color:#5B6660;padding:2px 0\">{{h.t}}</div></sc-for>\n      <sc-for list=\"{{b.mon.cells}}\" as=\"c\" hint-placeholder-count=\"35\">\n      <button onClick=\"{{c.go}}\" style=\"min-height:44px;border-radius:12px;border:1px solid {{c.bd}};background:{{c.bg}};color:{{c.fg}};font-size:14px;font-weight:500;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:0\">\n        <span>{{c.label}}</span>\n        <span style=\"display:flex;gap:3px;height:6px\"><span style=\"width:6px;height:6px;border-radius:3px;background:{{c.d1}}\"></span><span style=\"width:6px;height:6px;border-radius:3px;background:{{c.d2}}\"></span><span style=\"width:6px;height:6px;border-radius:3px;background:{{c.d3}}\"></span></span>\n      </button>\n      </sc-for>\n    </div>\n  </div>\n  </sc-if>\n\n  <!-- جدول حضور الأسبوع -->\n  <sc-if value=\"{{b.isWeek}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"display:flex;flex-direction:column;gap:10px\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;gap:8px\">\n      <button onClick=\"{{b.wk.next}}\" aria-label=\"الأسبوع التالي\" style=\"width:44px;height:44px;border-radius:12px;border:1px solid rgba(27,36,33,.18);background:#fff;display:flex;align-items:center;justify-content:center\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#1B2421\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-chevL\"></use></svg></button>\n      <div style=\"font-size:15px;font-weight:600;text-align:center\">{{b.wk.title}}</div>\n      <button onClick=\"{{b.wk.prev}}\" aria-label=\"الأسبوع السابق\" style=\"width:44px;height:44px;border-radius:12px;border:1px solid rgba(27,36,33,.18);background:#fff;display:flex;align-items:center;justify-content:center\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#1B2421\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-chevR\"></use></svg></button>\n    </div>\n    <div style=\"background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 0 0 1px rgba(27,36,33,.07)\">\n      <div style=\"display:flex;align-items:center;padding:8px 10px 6px 6px\">\n        <div style=\"width:78px;flex:none\"></div>\n        <sc-for list=\"{{b.wk.days}}\" as=\"d\" hint-placeholder-count=\"7\"><div style=\"flex:1;display:flex;flex-direction:column;align-items:center;font-size:11.5px;color:#5B6660;line-height:1.3\"><span>{{d.n}}</span><span style=\"font-size:14px;font-weight:500;color:{{d.fg}}\">{{d.d}}</span></div></sc-for>\n        <div style=\"width:30px;flex:none;text-align:left;font-size:11.5px;color:#5B6660\">أيام</div>\n      </div>\n      <sc-for list=\"{{b.wk.rows}}\" as=\"r\" hint-placeholder-count=\"4\">\n      <div style=\"display:flex;align-items:center;padding:3px 10px 3px 6px;border-top:1px solid #E6E9E4\">\n        <button onClick=\"{{r.go}}\" style=\"width:78px;flex:none;border:0;background:transparent;padding:8px 6px 8px 0;text-align:right;font-size:14px;font-weight:500;color:#1B2421;min-height:44px\">{{r.name}}</button>\n        <sc-for list=\"{{r.cells}}\" as=\"c\" hint-placeholder-count=\"7\"><button onClick=\"{{c.go}}\" style=\"flex:1;min-height:44px;border:0;background:transparent;display:flex;align-items:center;justify-content:center;padding:0\"><span style=\"width:28px;height:28px;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:600;background:{{c.bg}};color:{{c.fg}};border:{{c.bd}}\">{{c.t}}</span></button></sc-for>\n        <div style=\"width:30px;flex:none;text-align:left;font-size:13px;color:#5B6660\">{{r.tot}}</div>\n      </div>\n      </sc-for>\n    </div>\n    <div style=\"display:flex;gap:10px;flex-wrap:wrap;font-size:12px;color:#5B6660;padding:0 2px\">\n      <sc-for list=\"{{b.wk.legend}}\" as=\"g\" hint-placeholder-count=\"5\"><span style=\"display:flex;align-items:center;gap:4px\"><span style=\"width:18px;height:18px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:600;background:{{g.bg}};color:{{g.fg}};border:{{g.bd}}\">{{g.t}}</span>{{g.l}}</span></sc-for>\n    </div>\n  </div>\n  </sc-if>\n\n  <!-- مؤشرات -->\n  <sc-if value=\"{{b.isKpi}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"display:flex;gap:8px\">\n    <sc-for list=\"{{b.items}}\" as=\"k\" hint-placeholder-count=\"3\">\n    <div onClick=\"{{k.go}}\" style=\"flex:1;min-width:0;background:#fff;border-radius:14px;padding:10px 10px 11px;box-shadow:0 0 0 1px rgba(27,36,33,.07);cursor:{{k.cur}}\">\n      <div style=\"font-size:12px;color:#5B6660;display:flex;justify-content:space-between;align-items:center\"><span>{{k.label}}</span><sc-if value=\"{{k.hasGo}}\" hint-placeholder-val=\"{{false}}\"><span style=\"color:#6F7A74;font-size:16px;line-height:1\">‹</span></sc-if></div>\n      <div style=\"font-size:21px;font-weight:600;margin-top:3px;white-space:nowrap;color:{{k.endFg}}\">{{k.value}}</div>\n      <div style=\"font-size:12px;color:#5B6660;margin-top:1px;white-space:nowrap\">{{k.sub}}</div>\n    </div>\n    </sc-for>\n  </div>\n  </sc-if>\n\n  <!-- مفتاح تبويب (خاص / خارجي ...) -->\n  <sc-if value=\"{{b.isSeg}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"display:flex;gap:4px;background:#E6E9E4;border-radius:14px;padding:3px\">\n    <sc-for list=\"{{b.items}}\" as=\"s\" hint-placeholder-count=\"2\">\n    <button onClick=\"{{s.go}}\" aria-pressed=\"{{s.on}}\" style=\"flex:1;min-width:0;min-height:38px;border:0;border-radius:11px;font-size:14px;font-weight:500;display:flex;align-items:center;justify-content:center;gap:6px;background:{{s.segBg}};color:{{s.segFg}};box-shadow:{{s.segSh}}\">\n      <span>{{s.label}}</span>\n      <sc-if value=\"{{s.hasCount}}\" hint-placeholder-val=\"{{true}}\"><span style=\"font-size:12px;opacity:.8\">{{s.count}}</span></sc-if>\n    </button>\n    </sc-for>\n  </div>\n  </sc-if>\n\n  <!-- رقائق اختيار -->\n  <sc-if value=\"{{b.isChips}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n    <sc-for list=\"{{b.items}}\" as=\"c\" hint-placeholder-count=\"3\">\n    <button onClick=\"{{c.go}}\" aria-pressed=\"{{c.on}}\" style=\"min-height:44px;padding:0 14px;border-radius:999px;font-size:14px;font-weight:500;background:{{c.bg}};color:{{c.fg}};border:1px solid {{c.bd}}\">{{c.label}}</button>\n    </sc-for>\n  </div>\n  </sc-if>\n\n  <!-- قائمة صفوف -->\n  <sc-if value=\"{{b.isRows}}\" hint-placeholder-val=\"{{true}}\">\n  <div style=\"display:flex;flex-direction:column;gap:8px\">\n    <sc-if value=\"{{b.hasTitle}}\" hint-placeholder-val=\"{{true}}\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:36px\">\n      <h2 style=\"margin:0;font-size:16px;font-weight:600;letter-spacing:.1px\">{{b.title}}</h2>\n      <sc-if value=\"{{b.hasSort}}\" hint-placeholder-val=\"{{false}}\">\n      <button onClick=\"{{b.sortGo}}\" aria-label=\"ترتيب القائمة\" style=\"margin-inline-start:auto;min-height:44px;padding:0 10px;border-radius:12px;border:0;background:transparent;color:#46504B;font-size:13px;font-weight:500;display:flex;align-items:center;gap:4px\">\n        <span>{{b.sortLabel}}</span>\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"transform:{{b.sortRot}}\"><use href=\"#i-chevD\"></use></svg>\n      </button>\n      </sc-if>\n      <sc-if value=\"{{b.hasAct}}\" hint-placeholder-val=\"{{true}}\">\n      <button onClick=\"{{b.actGo}}\" style=\"min-height:44px;padding:0 12px;border-radius:12px;border:0;background:#E3F3EA;color:#14563A;font-size:13px;font-weight:600;display:flex;align-items:center;gap:5px\">\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-plus\"></use></svg>\n        <span>{{b.actLabel}}</span>\n      </button>\n      </sc-if>\n    </div>\n    </sc-if>\n    <div style=\"border-radius:16px;overflow:hidden;background:#E6E9E4;display:flex;flex-direction:column;gap:1px;box-shadow:0 0 0 1px rgba(27,36,33,.07)\">\n      <sc-for list=\"{{b.items}}\" as=\"r\" hint-placeholder-count=\"3\">\n      <sc-if value=\"{{r.isBtn}}\" hint-placeholder-val=\"{{true}}\">\n      <div style=\"display:flex;align-items:stretch;background:{{r.rbg}};margin-top:{{r.mt}}\"><button onClick=\"{{r.go}}\" onContextMenu=\"{{r.lp}}\" style=\"opacity:{{r.opc}};flex:1;min-width:0;box-sizing:border-box;min-height:{{r.minH}};padding:{{r.pad}};border:0;background:{{r.rbg}};color:#1B2421;text-align:right;display:flex;align-items:center;gap:12px\">\n        <sc-if value=\"{{r.hasIcon}}\" hint-placeholder-val=\"{{true}}\">\n        <span style=\"flex:none;width:28px;height:28px;border-radius:9px;background:{{r.icBg}};color:{{r.icFg}};display:flex;align-items:center;justify-content:center\">\n          <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#{{r.icon}}\"></use></svg>\n        </span>\n        </sc-if>\n        <span style=\"flex:1;min-width:0\">\n          <span style=\"display:block;font-size:{{r.tFs}};font-weight:{{r.tFw}};line-height:1.4;text-align:{{r.tAl}};color:{{r.tFg}}\">{{r.title}}<sc-if value=\"{{r.ph}}\" hint-placeholder-val=\"{{false}}\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#5B6660\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-label=\"صورة مرفقة\" style=\"margin-inline-start:6px;vertical-align:-2px\"><use href=\"#i-camera\"></use></svg></sc-if></span>\n          <sc-if value=\"{{r.hasSub}}\" hint-placeholder-val=\"{{true}}\"><span style=\"display:block;font-size:{{r.sFs}};color:#5B6660;line-height:1.5;margin-top:1px\">{{r.sub}}</span></sc-if>\n        </span>\n        <sc-if value=\"{{r.hasTag}}\" hint-placeholder-val=\"{{true}}\"><span style=\"flex:none;border-radius:999px;padding:3px 10px;font-size:12px;font-weight:500;white-space:nowrap;background:{{r.tagBg}};color:{{r.tagFg}}\">{{r.tag}}</span></sc-if>\n        <sc-if value=\"{{r.hasEnd}}\" hint-placeholder-val=\"{{true}}\">\n        <span style=\"flex:none;text-align:left\">\n          <sc-if value=\"{{r.hasEndCap}}\" hint-placeholder-val=\"{{false}}\"><span style=\"display:block;font-size:11px;color:#8A948E;white-space:nowrap\">{{r.endCap}}</span></sc-if>\n          <span style=\"display:block;font-size:{{r.eFs}};font-weight:{{r.eFw}};white-space:nowrap;color:{{r.endFg}}\">{{r.end}}</span>\n          <sc-if value=\"{{r.hasEndSub}}\" hint-placeholder-val=\"{{true}}\"><span style=\"display:block;font-size:{{r.subFs}};font-weight:{{r.subFw}};color:{{r.subFg}};white-space:nowrap\">{{r.endSub}}</span></sc-if>\n          <sc-if value=\"{{r.hasEndSub2}}\" hint-placeholder-val=\"{{true}}\"><span style=\"display:block;font-size:12px;color:#14563A;font-weight:500;white-space:nowrap\">{{r.endSub2}}</span></sc-if>\n        </span>\n        </sc-if>\n        <sc-if value=\"{{r.hasEnd2}}\" hint-placeholder-val=\"{{false}}\">\n        <span style=\"flex:none;text-align:left;margin-inline-start:12px;padding-inline-start:12px;border-inline-start:1px solid #EDEFEA\">\n          <span style=\"display:block;font-size:11px;color:#8A948E;white-space:nowrap\">{{r.end2Cap}}</span>\n          <span style=\"display:block;font-size:{{r.eFs}};font-weight:{{r.eFw}};white-space:nowrap;color:{{r.end2Fg}}\">{{r.end2}}</span>\n          <sc-if value=\"{{r.hasEnd2Sub}}\" hint-placeholder-val=\"{{false}}\"><span style=\"display:block;font-size:12px;color:#14563A;font-weight:500;white-space:nowrap\">{{r.end2Sub}}</span></sc-if>\n        </span>\n        </sc-if>\n        <sc-if value=\"{{r.chev}}\" hint-placeholder-val=\"{{true}}\">\n        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#8A948E\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none\"><use href=\"#i-chevL\"></use></svg>\n        </sc-if>\n      </button>\n      <sc-if value=\"{{r.hasUndo}}\" hint-placeholder-val=\"{{false}}\"><button onClick=\"{{r.undoGo}}\" style=\"flex:none;align-self:center;margin:0 10px;min-height:40px;padding:0 14px;border-radius:999px;border:1px solid rgba(20,86,58,.45);background:#fff;color:#14563A;font-size:13px;font-weight:600\">استرجاع</button></sc-if>\n      <sc-if value=\"{{r.hasX}}\" hint-placeholder-val=\"{{false}}\"><button onClick=\"{{r.xGo}}\" aria-label=\"إخفاء التنبيه\" style=\"flex:none;width:48px;border:0;background:transparent;color:#5B6660;display:flex;align-items:center;justify-content:center\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" aria-hidden=\"true\"><use href=\"#i-x\"></use></svg></button></sc-if>\n      </div>\n      </sc-if>\n      <sc-if value=\"{{r.isStep}}\" hint-placeholder-val=\"{{false}}\">\n      <div style=\"background:#fff;padding:8px 8px 8px 12px;display:flex;align-items:center;gap:2px\">\n        <span style=\"flex:1;min-width:0;padding-inline-end:8px\">\n          <span style=\"display:block;font-size:15px;font-weight:500\">{{r.title}}</span>\n          <sc-if value=\"{{r.hasBadge}}\" hint-placeholder-val=\"{{false}}\"><span style=\"display:inline-block;margin-top:3px;padding:1px 8px;border-radius:999px;background:#FFF1D6;color:#6B3F00;font-size:11.5px;font-weight:500\">{{r.badge}}</span></sc-if>\n          <span style=\"display:block;font-size:12.5px;color:#5B6660;margin-top:1px\">{{r.sub}}</span>\n          <sc-if value=\"{{r.hasSub2}}\" hint-placeholder-val=\"{{false}}\"><span style=\"display:block;font-size:12.5px;color:#0B63B8;margin-top:1px\">{{r.sub2}}</span></sc-if>\n          <sc-if value=\"{{r.hasHintGo}}\" hint-placeholder-val=\"{{false}}\"><button onClick=\"{{r.hintGo}}\" aria-label=\"اضبط على قيمة الوصفة\" style=\"display:block;min-height:34px;padding:0;border:0;background:transparent;font-size:12.5px;font-weight:500;color:#14563A;text-decoration:underline dotted;text-underline-offset:4px;text-align:right\">{{r.hintTxt}}</button></sc-if>\n          <sc-if value=\"{{r.hasWarn}}\" hint-placeholder-val=\"{{false}}\"><span style=\"display:block;font-size:12.5px;font-weight:500;color:#8E1B10;margin-top:2px\">{{r.warn}}</span></sc-if>\n        </span>\n        <button onClick=\"{{r.minus}}\" aria-label=\"أقل\" style=\"flex:none;width:44px;height:44px;border:0;background:transparent;padding:0;display:flex;align-items:center;justify-content:center\"><span style=\"width:34px;height:34px;border-radius:11px;border:1px solid rgba(27,36,33,.25);background:#fff;color:#1B2421;display:flex;align-items:center;justify-content:center\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><use href=\"#i-minus\"></use></svg></span></button>\n        <button onClick=\"{{r.edit}}\" aria-label=\"تعديل الكمية أو إزالة الصنف\" style=\"flex:none;min-width:60px;min-height:44px;border:0;border-bottom:2px dotted #8A948E;border-radius:0;background:transparent;color:#1B2421;text-align:center;white-space:nowrap;padding:0 2px\"><span style=\"display:block;font-size:17px;font-weight:500\">{{r.val}}</span><span style=\"display:block;font-size:11.5px;color:#5B6660\">{{r.unit}}</span></button>\n        <button onClick=\"{{r.plus}}\" aria-label=\"أكثر\" style=\"flex:none;width:44px;height:44px;border:0;background:transparent;padding:0;display:flex;align-items:center;justify-content:center\"><span style=\"width:34px;height:34px;border-radius:11px;border:1px solid rgba(27,36,33,.25);background:#fff;color:#1B2421;display:flex;align-items:center;justify-content:center\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><use href=\"#i-plus\"></use></svg></span></button>\n      </div>\n      </sc-if>\n      </sc-for>\n      <sc-if value=\"{{b.hasEmpty}}\" hint-placeholder-val=\"{{false}}\"><div style=\"background:#fff;padding:20px 16px 18px;color:#5B6660;font-size:14px;text-align:center;line-height:1.7;display:flex;flex-direction:column;align-items:center;gap:6px\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B7BFB9\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-doc\"></use></svg><div>{{b.emptyText}}</div></div></sc-if>\n    </div>\n  </div>\n  </sc-if>\n\n  <!-- إجراءات سريعة -->\n  <sc-if value=\"{{b.isGrid}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:8px\">\n    <sc-for list=\"{{b.items}}\" as=\"g\" hint-placeholder-count=\"4\">\n    <button onClick=\"{{g.go}}\" style=\"min-height:60px;border:0;border-radius:16px;padding:8px 12px;display:flex;align-items:center;gap:10px;text-align:right;background:{{g.icBg}};color:{{g.icFg}};font-size:14px;font-weight:600\">\n      <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none\"><use href=\"#{{g.icon}}\"></use></svg>\n      <span style=\"flex:1;min-width:0;line-height:1.35\">{{g.label}}</span>\n    </button>\n    </sc-for>\n  </div>\n  </sc-if>\n\n  <!-- ملاحظة -->\n  <sc-if value=\"{{b.isNote}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"background:{{b.bg}};color:{{b.fg}};border-radius:14px;padding:12px 14px;font-size:14px;line-height:1.7;display:flex;gap:10px;align-items:flex-start\">\n    <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none;margin-top:2px\"><use href=\"#{{b.icon}}\"></use></svg>\n    <div style=\"flex:1;min-width:0\">\n      <div>{{b.text}}</div>\n      <sc-if value=\"{{b.hasAct}}\" hint-placeholder-val=\"{{false}}\"><button onClick=\"{{b.actGo}}\" style=\"margin-top:6px;min-height:44px;padding:0 14px;border-radius:12px;border:1px solid {{b.fg}};background:transparent;color:{{b.fg}};font-size:13px;font-weight:600\">{{b.actLabel}}</button></sc-if>\n    </div>\n  </div>\n  </sc-if>\n\n  <!-- بطاقة كبيرة (رصيد) -->\n  <sc-if value=\"{{b.isBig}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"background:#1B2421;color:#fff;border-radius:18px;padding:16px\">\n    <div style=\"font-size:13px;color:#D5DAD6\">{{b.label}}</div>\n    <div style=\"font-size:32px;font-weight:600;margin-top:2px;white-space:nowrap\">{{b.value}}</div>\n    <sc-if value=\"{{b.hasV2}}\" hint-placeholder-val=\"{{false}}\"><div style=\"font-size:32px;font-weight:600;margin-top:2px;white-space:nowrap\">{{b.value2}}</div></sc-if>\n    <div style=\"font-size:13px;color:#D5DAD6;margin-top:2px;line-height:1.7;white-space:pre-line\">{{b.text}}</div>\n  </div>\n  </sc-if>\n\n  <!-- أزرار -->\n  <sc-if value=\"{{b.isActs}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"display:flex;gap:8px\">\n    <sc-for list=\"{{b.items}}\" as=\"a\" hint-placeholder-count=\"2\">\n    <button onClick=\"{{a.go}}\" aria-label=\"{{a.title}}\" style=\"flex:1;min-width:0;min-height:62px;border:0;border-radius:14px;background:{{a.abg}};color:{{a.afg}};display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:6px 2px\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#{{a.icon}}\"></use></svg>\n      <span style=\"font-size:12px;font-weight:500;white-space:nowrap\">{{a.title}}</span>\n    </button>\n    </sc-for>\n  </div>\n  </sc-if>\n\n  <sc-if value=\"{{b.isBtns}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"display:flex;gap:8px\">\n    <sc-for list=\"{{b.items}}\" as=\"n\" hint-placeholder-count=\"2\">\n    <button onClick=\"{{n.go}}\" style=\"flex:1;min-width:0;min-height:48px;border-radius:14px;border:1px solid {{n.bd}};background:{{n.bg}};color:{{n.fg}};font-size:14px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:6px;padding:0 8px\">\n      <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none\"><use href=\"#{{n.icon}}\"></use></svg>\n      <span>{{n.label}}</span>\n    </button>\n    </sc-for>\n  </div>\n  </sc-if>\n\n  <!-- مستند تقرير -->\n  <sc-if value=\"{{b.isPaper}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"flex:none;background:#fff;border-radius:10px;box-shadow:0 1px 4px rgba(27,36,33,.16),0 0 0 1px rgba(27,36,33,.07);overflow:hidden\">\n    <div style=\"background:#14563A;color:#fff;padding:14px 14px 12px\">\n      <div style=\"display:flex;align-items:center;gap:10px\">\n        <div style=\"flex:none;width:42px;height:42px;border-radius:11px;background:rgba(255,255,255,.16);display:flex;align-items:center;justify-content:center\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-pot\"></use></svg></div>\n        <div style=\"flex:1;min-width:0\"><div style=\"font-size:13px;opacity:.85\">{{b.pap.org}}</div><div style=\"font-size:19px;font-weight:600;line-height:1.35\">{{b.pap.title}}</div></div>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;gap:8px;margin-top:10px;font-size:12.5px;opacity:.92;line-height:1.6\"><span>{{b.pap.date}}</span><span>{{b.pap.sub}}</span></div>\n    </div>\n    <sc-if value=\"{{b.pap.hasLead}}\" hint-placeholder-val=\"{{false}}\"><div style=\"padding:10px 14px;font-size:13.5px;line-height:1.7;color:#1B2421;border-bottom:1px solid #E6E9E4\">{{b.pap.lead}}</div></sc-if>\n    <sc-if value=\"{{b.pap.hasTiles}}\" hint-placeholder-val=\"{{false}}\">\n    <div style=\"display:flex;border-bottom:1px solid #E6E9E4;background:#FAFBF9\">\n      <sc-for list=\"{{b.pap.tiles}}\" as=\"t\" hint-placeholder-count=\"3\">\n      <div style=\"flex:1;min-width:0;padding:10px 4px;text-align:center;border-inline-start:1px solid #E6E9E4\"><div style=\"font-size:21px;font-weight:500;white-space:nowrap\">{{t.value}}</div><div style=\"font-size:12px;color:#5B6660\">{{t.label}}</div></div>\n      </sc-for>\n    </div>\n    </sc-if>\n    <div style=\"padding:2px 12px 14px\">\n      <sc-for list=\"{{b.pap.secs}}\" as=\"s\" hint-placeholder-count=\"2\">\n      <div style=\"margin-top:14px;display:flex;align-items:center;gap:8px\"><span style=\"flex:none;width:4px;height:16px;border-radius:2px;background:#14563A\"></span><span style=\"font-size:14.5px;font-weight:600\">{{s.title}}</span></div>\n      <sc-if value=\"{{s.isGrid}}\" hint-placeholder-val=\"{{false}}\">\n      <div style=\"margin-top:6px;border:1px solid #D9DDD7;border-radius:8px;overflow:hidden\">\n        <div style=\"display:grid;grid-template-columns:1fr 1fr\">\n          <sc-for list=\"{{s.cells}}\" as=\"g\" hint-placeholder-count=\"4\"><div style=\"padding:6px 10px;display:flex;justify-content:space-between;align-items:center;gap:6px;min-width:0;border-top:1px solid #EDEFEA;{{g.st}}\"><div style=\"min-width:0\"><div style=\"font-size:13px;font-weight:500;color:{{g.fg}}\">{{g.name}}</div><sc-if value=\"{{g.hasSub}}\" hint-placeholder-val=\"{{false}}\"><div style=\"font-size:11px;color:#5B6660;line-height:1.4\">{{g.sub}}</div></sc-if></div><div style=\"flex:none;font-size:16px;font-weight:500;color:{{g.fg}}\">{{g.val}}</div></div></sc-for>\n        </div>\n        <sc-if value=\"{{s.hasTotal}}\" hint-placeholder-val=\"{{false}}\"><div style=\"display:flex;justify-content:space-between;padding:8px 12px;background:#D5E8DC;font-size:13.5px;font-weight:700;color:#14563A;border-top:2px solid #14563A\"><span>{{s.totLabel}}</span><span>{{s.totVal}}</span></div></sc-if>\n      </div>\n      </sc-if>\n      <sc-if value=\"{{s.isTab}}\" hint-placeholder-val=\"{{false}}\">\n      <div style=\"margin-top:6px;border:1px solid #D9DDD7;border-radius:8px;overflow:hidden\">\n        <div style=\"display:grid;grid-template-columns:{{s.cols}};background:#EAF1EC;font-size:12px;font-weight:600;color:#14563A\">\n          <sc-for list=\"{{s.head}}\" as=\"h\" hint-placeholder-count=\"3\"><div style=\"padding:7px 8px;{{h.st}}\">{{h.t}}</div></sc-for>\n        </div>\n        <sc-for list=\"{{s.rows}}\" as=\"r\" hint-placeholder-count=\"3\">\n        <div style=\"display:grid;grid-template-columns:{{s.cols}};border-top:{{r.bt}};background:{{r.bg}};font-size:13.5px;align-items:center\">\n          <sc-for list=\"{{r.cells}}\" as=\"c\" hint-placeholder-count=\"3\"><div style=\"padding:5px 8px;min-width:0;{{c.st}}\">{{c.t}}<span style=\"font-size:11px;font-weight:400;color:#8A948E;margin-inline-start:3px\">{{c.u}}</span><sc-if value=\"{{c.hasSub}}\" hint-placeholder-val=\"{{false}}\"><div style=\"font-size:11.5px;color:#5B6660;font-weight:400;line-height:1.5\">{{c.sub}}</div></sc-if></div></sc-for>\n        </div>\n        </sc-for>\n        <sc-if value=\"{{s.hasEmpty}}\" hint-placeholder-val=\"{{false}}\"><div style=\"padding:12px;text-align:center;font-size:13px;color:#5B6660\">{{s.empty}}</div></sc-if>\n      </div>\n      </sc-if>\n      </sc-for>\n      <sc-for list=\"{{b.pap.notes}}\" as=\"n\" hint-placeholder-count=\"1\">\n      <div style=\"margin-top:10px;font-size:12.5px;color:#5B6660;line-height:1.7\">{{n.t}}</div>\n      </sc-for>\n    </div>\n    <div style=\"border-top:1px dashed #D9DDD7;padding:9px 14px;display:flex;justify-content:space-between;font-size:11.5px;color:#7A857F\"><span>{{b.pap.org}}</span><span>{{b.pap.foot}}</span></div>\n  </div>\n  </sc-if>\n\n  <!-- نص جاهز للنسخ (تقرير) -->\n  <sc-if value=\"{{b.isPre}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"background:#fff;border-radius:16px;padding:14px;box-shadow:0 0 0 1px rgba(27,36,33,.07);font-size:14px;line-height:1.9;white-space:pre-wrap\">{{b.text}}</div>\n  </sc-if>\n\n  <!-- حقل يفتح قائمة اختيار -->\n  <sc-if value=\"{{b.isPick}}\" hint-placeholder-val=\"{{false}}\">\n  <button onClick=\"{{b.go}}\" style=\"width:100%;box-sizing:border-box;min-height:64px;text-align:right;display:flex;align-items:center;gap:12px;background:#fff;border:0;border-radius:16px;padding:10px 14px;box-shadow:0 0 0 1px {{b.bd}};color:#1B2421\">\n    <span style=\"flex:1;min-width:0\">\n      <span style=\"display:block;font-size:12px;color:#5B6660\">{{b.label}}</span>\n      <span style=\"display:block;font-size:17px;font-weight:600;margin-top:1px;color:{{b.fg}}\">{{b.value}}</span>\n    </span>\n    <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#5B6660\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none\"><use href=\"#i-chevD\"></use></svg>\n  </button>\n  </sc-if>\n\n  <!-- عدّاد كبير (عدد القدور) -->\n  <sc-if value=\"{{b.isStepper}}\" hint-placeholder-val=\"{{false}}\">\n  <div style=\"display:flex;align-items:center;gap:10px;background:#fff;border-radius:16px;padding:12px 14px;box-shadow:0 0 0 1px rgba(27,36,33,.07)\">\n    <div style=\"flex:1;min-width:0\">\n      <div style=\"font-size:15px;font-weight:600\">{{b.label}}</div>\n      <div style=\"font-size:12.5px;color:#5B6660;margin-top:1px;line-height:1.5\">{{b.text}}</div>\n    </div>\n    <button onClick=\"{{b.minus}}\" aria-label=\"أقل\" style=\"flex:none;width:44px;height:44px;border:0;background:transparent;padding:0;display:flex;align-items:center;justify-content:center\"><span style=\"width:34px;height:34px;border-radius:11px;border:1px solid rgba(27,36,33,.25);background:#fff;color:#1B2421;display:flex;align-items:center;justify-content:center\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><use href=\"#i-minus\"></use></svg></span></button>\n    <button onClick=\"{{b.edit}}\" aria-label=\"اكتب العدد\" style=\"flex:none;min-width:48px;min-height:44px;border:0;border-bottom:2px dotted #8A948E;border-radius:0;background:transparent;color:#1B2421;text-align:center;font-size:24px;font-weight:600;padding:0 4px\">{{b.value}}</button>\n    <button onClick=\"{{b.plus}}\" aria-label=\"أكثر\" style=\"flex:none;width:44px;height:44px;border:0;background:transparent;padding:0;display:flex;align-items:center;justify-content:center\"><span style=\"width:34px;height:34px;border-radius:11px;background:#14563A;color:#fff;display:flex;align-items:center;justify-content:center\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><use href=\"#i-plus\"></use></svg></span></button>\n  </div>\n  </sc-if>\n\n  <!-- حقل إدخال نصي -->\n  <sc-if value=\"{{b.isInput}}\" hint-placeholder-val=\"{{false}}\">\n  <label style=\"display:block;background:#fff;border-radius:16px;padding:10px 14px 12px;box-shadow:0 0 0 1px rgba(27,36,33,.1)\">\n    <span style=\"display:block;font-size:12px;color:#5B6660\">{{b.label}}</span>\n    <input value=\"{{b.value}}\" onInput=\"{{b.onInput}}\" placeholder=\"{{b.ph}}\" inputmode=\"{{b.mode}}\" style=\"width:100%;box-sizing:border-box;margin-top:4px;min-height:44px;border:0;outline:0;background:transparent;font-size:17px;font-weight:500;color:#1B2421;padding:0\">\n  </label>\n  </sc-if>\n\n</sc-for>\n</div>\n\n<!-- شريط الإجراء السفلي للصفحات الفرعية -->\n<sc-if value=\"{{hasFooter}}\" hint-placeholder-val=\"{{false}}\">\n<div style=\"flex:none;display:flex;gap:8px;padding:10px 16px 14px;background:#fff;border-top:1px solid #E1E5DF\">\n  <sc-if value=\"{{hasFt2}}\" hint-placeholder-val=\"{{false}}\">\n  <button onClick=\"{{ft2Go}}\" style=\"flex:none;min-height:52px;padding:0 16px;border-radius:14px;border:1px solid {{ft2Bd}};background:#fff;color:{{ft2Fg}};font-size:15px;font-weight:600\">{{ft2Label}}</button>\n  </sc-if>\n  <button onClick=\"{{ftGo}}\" aria-disabled=\"{{ftDisabled}}\" style=\"flex:1;min-width:0;min-height:52px;border-radius:14px;border:0;background:{{ftBg}};color:{{ftFg}};font-size:16px;font-weight:600\">{{ftLabel}}</button>\n</div>\n</sc-if>\n\n<!-- التنقل الرئيسي -->\n<sc-if value=\"{{isMain}}\" hint-placeholder-val=\"{{true}}\">\n<nav aria-label=\"التنقل\" style=\"flex:none;display:flex;background:#fff;border-top:1px solid #E1E5DF;padding:4px 4px 10px\">\n  <sc-for list=\"{{tabs}}\" as=\"t\" hint-placeholder-count=\"5\">\n  <button onClick=\"{{t.go}}\" aria-current=\"{{t.cur}}\" style=\"flex:1;min-width:0;min-height:56px;border:0;background:transparent;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;color:{{t.fg}};font-size:12px;font-weight:{{t.fw}}\">\n    <span style=\"position:relative;display:flex;width:44px;height:28px;align-items:center;justify-content:center;border-radius:14px;background:{{t.pill}}\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#{{t.icon}}\"></use></svg>\n      <sc-if value=\"{{t.hasBadge}}\" hint-placeholder-val=\"{{false}}\"><span style=\"position:absolute;top:-3px;left:3px;min-width:18px;height:18px;border-radius:9px;background:#B3261E;color:#fff;font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center;padding:0 4px;box-sizing:border-box\">{{t.badge}}</span></sc-if>\n    </span>\n    <span>{{t.label}}</span>\n  </button>\n  </sc-for>\n</nav>\n</sc-if>\n\n<!-- نافذة سفلية عامة: اختر من الموجود أو أضف جديدًا -->\n<sc-if value=\"{{shOn}}\" hint-placeholder-val=\"{{false}}\">\n<div style=\"position:absolute;inset:0;z-index:20;display:flex;flex-direction:column;justify-content:flex-end\">\n  <button aria-label=\"إغلاق النافذة\" onClick=\"{{shClose}}\" style=\"position:absolute;inset:0;border:0;padding:0;background:rgba(27,36,33,.5)\"></button>\n  <div role=\"dialog\" aria-modal=\"true\" aria-label=\"{{shTitle}}\" style=\"position:relative;background:#fff;border-radius:22px 22px 0 0;max-height:90%;display:flex;flex-direction:column;box-shadow:0 -8px 30px rgba(0,0,0,.2)\">\n    <div style=\"flex:none;padding:10px 16px 6px\">\n      <div style=\"width:40px;height:4px;border-radius:2px;background:#D5D9D3;margin:0 auto 8px\"></div>\n      <div style=\"display:flex;align-items:center;gap:10px\">\n        <div style=\"flex:1;min-width:0\">\n          <div style=\"font-size:18px;font-weight:600;line-height:1.4\">{{shTitle}}</div>\n          <sc-if value=\"{{shHasSub}}\" hint-placeholder-val=\"{{true}}\"><div style=\"font-size:13px;color:#5B6660;line-height:1.5\">{{shSub}}</div></sc-if>\n        </div>\n        <button onClick=\"{{shClose}}\" aria-label=\"إغلاق\" style=\"flex:none;width:44px;height:44px;border-radius:14px;border:0;background:#F0F2EE;color:#1B2421;display:flex;align-items:center;justify-content:center\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" aria-hidden=\"true\"><use href=\"#i-x\"></use></svg>\n        </button>\n      </div>\n    </div>\n    <div style=\"flex:1;min-height:0;overflow-y:auto;padding:4px 16px 12px;display:flex;flex-direction:column;gap:10px\">\n\n      <sc-if value=\"{{shHasSearch}}\" hint-placeholder-val=\"{{false}}\">\n      <label style=\"display:flex;align-items:center;gap:8px;background:#F0F2EE;border-radius:14px;padding:0 12px\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#5B6660\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none\"><use href=\"#i-search\"></use></svg>\n        <input value=\"{{shQ}}\" onInput=\"{{shOnQ}}\" placeholder=\"{{shPh}}\" style=\"flex:1;min-width:0;min-height:48px;border:0;outline:0;background:transparent;font-size:16px;color:#1B2421\">\n      </label>\n      </sc-if>\n\n      <sc-if value=\"{{shHasActs}}\" hint-placeholder-val=\"{{false}}\">\n      <div style=\"flex:none;display:flex;gap:8px\">\n        <sc-for list=\"{{shActs}}\" as=\"a\" hint-placeholder-count=\"4\">\n        <button onClick=\"{{a.go}}\" aria-label=\"{{a.title}}\" style=\"flex:1;min-width:0;min-height:62px;border:0;border-radius:14px;background:#F0F2EE;color:#1B2421;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:6px 2px\">\n          <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#{{a.icon}}\"></use></svg>\n          <span style=\"font-size:12px;font-weight:500;white-space:nowrap\">{{a.title}}</span>\n        </button>\n        </sc-for>\n      </div>\n      </sc-if>\n\n      <sc-if value=\"{{shHasRows}}\" hint-placeholder-val=\"{{false}}\">\n      <div style=\"flex:none;border-radius:14px;overflow:hidden;background:#E6E9E4;display:flex;flex-direction:column;gap:1px;box-shadow:0 0 0 1px rgba(27,36,33,.07)\">\n        <sc-if value=\"{{shHasCols}}\" hint-placeholder-val=\"{{false}}\"><div style=\"display:flex;align-items:center;gap:8px;padding:7px 14px;background:#F7F8F5;font-size:12px;color:#5B6660\"><span style=\"flex:1\">{{shCol0}}</span><span style=\"flex:none;width:60px;text-align:center\">{{shCol1}}</span><span style=\"flex:none;width:84px;text-align:center\">{{shCol2}}</span><span style=\"flex:none;width:84px;text-align:center\">{{shCol3}}</span></div></sc-if>\n        <sc-for list=\"{{shRows}}\" as=\"r\" hint-placeholder-count=\"4\">\n        <button onClick=\"{{r.go}}\" onContextMenu=\"{{r.lp}}\" aria-pressed=\"{{r.sel}}\" style=\"width:100%;box-sizing:border-box;min-height:56px;padding:8px 14px;border:0;background:{{r.rbg}};color:#1B2421;text-align:right;display:flex;align-items:center;gap:10px\">\n          <span style=\"flex:1;min-width:0\">\n            <span style=\"display:block;font-size:15px;font-weight:500;line-height:1.4\">{{r.title}}<sc-if value=\"{{r.ph}}\" hint-placeholder-val=\"{{false}}\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#5B6660\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-label=\"صورة مرفقة\" style=\"margin-inline-start:6px;vertical-align:-2px\"><use href=\"#i-camera\"></use></svg></sc-if></span>\n            <sc-if value=\"{{r.hasSub}}\" hint-placeholder-val=\"{{true}}\"><span style=\"display:block;font-size:12.5px;color:#5B6660;line-height:1.5;white-space:pre-line\">{{r.sub}}</span></sc-if>\n          </span>\n          <sc-if value=\"{{r.hasCols}}\" hint-placeholder-val=\"{{false}}\"><span style=\"flex:none;width:60px;text-align:center;font-size:13px;color:#5B6660;white-space:nowrap\">{{r.c0}}</span><span style=\"flex:none;width:84px;text-align:center\"><span style=\"display:block;font-size:14px;font-weight:500;white-space:nowrap\">{{r.c1}}</span><span style=\"display:block;font-size:11px;color:#5B6660;white-space:nowrap\">{{r.c1s}}</span></span><span style=\"flex:none;width:84px;text-align:center\"><span style=\"display:block;font-size:14px;font-weight:500;white-space:nowrap;color:{{r.c2Fg}}\">{{r.c2}}</span><span style=\"display:block;font-size:11px;white-space:nowrap;color:{{r.c2Fg}}\">{{r.c2s}}</span></span></sc-if>\n          <sc-if value=\"{{r.hasTag}}\" hint-placeholder-val=\"{{true}}\"><span style=\"flex:none;border-radius:999px;padding:3px 10px;font-size:12px;font-weight:500;white-space:nowrap;background:{{r.tagBg}};color:{{r.tagFg}}\">{{r.tag}}</span></sc-if>\n          <sc-if value=\"{{r.hasEnd}}\" hint-placeholder-val=\"{{false}}\"><span style=\"flex:none;text-align:left\"><span style=\"display:block;font-size:16px;font-weight:500;white-space:nowrap;color:{{r.endFg}}\">{{r.end}}</span><sc-if value=\"{{r.hasEndSub}}\" hint-placeholder-val=\"{{false}}\"><span style=\"display:block;font-size:12px;white-space:nowrap;color:{{r.endFg}}\">{{r.endSub}}</span></sc-if></span></sc-if>\n          <sc-if value=\"{{r.sel}}\" hint-placeholder-val=\"{{false}}\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#14563A\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none\"><use href=\"#i-check\"></use></svg></sc-if>\n        </button>\n        </sc-for>\n      </div>\n      </sc-if>\n\n      <sc-if value=\"{{shHasEmpty}}\" hint-placeholder-val=\"{{false}}\"><div style=\"color:#5B6660;font-size:14px;text-align:center;padding:10px 0;line-height:1.7\">{{shEmpty}}</div></sc-if>\n\n      <sc-if value=\"{{shHasDup}}\" hint-placeholder-val=\"{{false}}\">\n      <div style=\"background:#FFF1D6;color:#6B3F00;border-radius:12px;padding:10px 12px;font-size:13.5px;line-height:1.7;display:flex;gap:8px;align-items:flex-start\">\n        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none;margin-top:3px\"><use href=\"#i-alert\"></use></svg>\n        <span>{{shDup}}</span>\n      </div>\n      </sc-if>\n\n      <sc-if value=\"{{shHasAdd}}\" hint-placeholder-val=\"{{false}}\">\n      <button onClick=\"{{shAddGo}}\" style=\"width:100%;box-sizing:border-box;min-height:56px;border-radius:14px;border:1.5px dashed #14563A;background:#F2F9F5;color:#14563A;font-size:15px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8px;padding:0 12px\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><use href=\"#i-plus\"></use></svg>\n        <span>{{shAddLabel}}</span>\n      </button>\n      </sc-if>\n\n      <sc-if value=\"{{shHasAdd2}}\" hint-placeholder-val=\"{{false}}\">\n      <button onClick=\"{{shAdd2Go}}\" style=\"width:100%;box-sizing:border-box;min-height:56px;border-radius:14px;border:1.5px dashed #8A948E;background:#FFFFFF;color:#3E4843;font-size:15px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8px;padding:6px 12px;text-align:center\">\n        <span>{{shAdd2Label}}</span>\n      </button>\n      </sc-if>\n\n      <sc-for list=\"{{shFields}}\" as=\"f\" hint-placeholder-count=\"2\">\n      <div class=\"ff\" style=\"display:flex;flex-direction:column;gap:6px\">\n        <div style=\"display:flex;flex-direction:{{f.fd}};align-items:{{f.ai}};gap:{{f.gp}}\">\n        <div style=\"font-size:13px;font-weight:500;color:#3E4843;flex:{{f.lf}}\">{{f.label}}</div>\n        <sc-if value=\"{{f.isText}}\" hint-placeholder-val=\"{{true}}\">\n        <div class=\"fw\" style=\"display:flex;flex-direction:column;gap:8px;width:{{f.cw}};flex:none\">\n        <input type=\"{{f.itype}}\" min=\"{{f.min}}\" max=\"{{f.max}}\" value=\"{{f.value}}\" onInput=\"{{f.onInput}}\" onKeyDown=\"{{f.onKey}}\" dir=\"{{f.dir}}\" placeholder=\"{{f.ph}}\" inputmode=\"{{f.mode}}\" style=\"width:100%;box-sizing:border-box;min-height:40px;border-radius:12px;border:1px solid rgba(27,36,33,.22);background:#fff;padding:0 14px;font-size:16px;color:#1B2421;outline:0;text-align:{{f.ta}}\">\n        <sc-if value=\"{{f.isCalc}}\" hint-placeholder-val=\"{{false}}\">\n        <button class=\"ci\" data-ci=\"1\" aria-label=\"آلة حاسبة\" style=\"position:absolute;left:4px;top:2px;width:36px;height:36px;border:0;background:transparent;color:#8A948E;align-items:center;justify-content:center\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"5\" y=\"2.5\" width=\"14\" height=\"19\" rx=\"2.5\"></rect><path d=\"M8.5 7h7M8.5 12h.01M12 12h.01M15.5 12h.01M8.5 16.5h.01M12 16.5h.01M15.5 16.5h.01\"></path></svg></button>\n        </sc-if>\n        </div>\n        </sc-if>\n        <sc-if value=\"{{f.isGrow}}\" hint-placeholder-val=\"{{false}}\">\n        <div class=\"fw\" style=\"display:flex;flex-direction:column;gap:8px;width:{{f.cw}};flex:none\">\n        <textarea class=\"gr\" rows=\"1\" onInput=\"{{f.onInput}}\" onKeyDown=\"{{f.onKey}}\" dir=\"{{f.dir}}\" placeholder=\"{{f.ph}}\" style=\"width:100%;box-sizing:border-box;min-height:40px;border-radius:12px;border:1px solid rgba(27,36,33,.22);background:#fff;padding:8px 14px;font-size:16px;line-height:1.5;color:#1B2421;outline:0;resize:none;overflow:hidden;font-family:inherit;text-align:{{f.ta}}\">{{f.value}}</textarea>\n        </div>\n        </sc-if>\n        <sc-if value=\"{{f.hasRm}}\" hint-placeholder-val=\"{{false}}\">\n        <button onClick=\"{{f.rm}}\" aria-label=\"إزالة\" style=\"flex:none;width:34px;height:34px;border:0;border-radius:999px;background:transparent;color:#8A948E;display:flex;align-items:center;justify-content:center\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-x\"></use></svg></button>\n        </sc-if>\n        <sc-if value=\"{{f.isArea}}\" hint-placeholder-val=\"{{false}}\">\n        <textarea onInput=\"{{f.onInput}}\" placeholder=\"{{f.ph}}\" rows=\"6\" style=\"width:100%;box-sizing:border-box;min-height:132px;border-radius:14px;border:1px solid rgba(27,36,33,.22);background:#fff;padding:12px 14px;font-size:16px;line-height:1.7;color:#1B2421;outline:0;resize:vertical;font-family:inherit\">{{f.value}}</textarea>\n        </sc-if>\n        <sc-if value=\"{{f.isChips}}\" hint-placeholder-val=\"{{false}}\">\n        <div style=\"display:flex;flex-wrap:wrap;gap:8px;flex-direction:{{f.cdir}};background:{{f.cbg}};padding:{{f.cpad}};border-radius:14px\">\n          <sc-for list=\"{{f.chips}}\" as=\"c\" hint-placeholder-count=\"3\">\n          <button onClick=\"{{c.go}}\" aria-pressed=\"{{c.on}}\" style=\"flex:{{f.cflex}};text-align:{{f.ctal}};justify-content:{{f.cjc}};min-height:44px;min-width:56px;padding:0 14px;border-radius:999px;font-size:14px;font-weight:500;background:{{c.bg}};color:{{c.fg}};border:1px solid {{c.bd}}\">{{c.label}}</button>\n          </sc-for>\n        </div>\n        </sc-if>\n        <sc-if value=\"{{f.phEmpty}}\" hint-placeholder-val=\"{{false}}\">\n        <button onClick=\"{{f.phOpen}}\" aria-label=\"إرفاق صورة\" style=\"flex:none;width:48px;height:48px;border-radius:12px;border:1px solid rgba(27,36,33,.22);background:#EEF1EC;color:#14563A;display:flex;align-items:center;justify-content:center\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-camera\"></use></svg></button>\n        </sc-if>\n        <sc-if value=\"{{f.phMenu}}\" hint-placeholder-val=\"{{false}}\">\n        <div style=\"display:flex;gap:8px\">\n          <button onClick=\"{{f.phCam}}\" style=\"flex:1;min-height:56px;border-radius:14px;border:0;background:#14563A;color:#fff;font-size:15px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-camera\"></use></svg>التقاط صورة</button>\n          <button onClick=\"{{f.phFile}}\" style=\"flex:1;min-height:56px;border-radius:14px;border:1px solid rgba(27,36,33,.25);background:#fff;color:#1B2421;font-size:15px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-image\"></use></svg>من الجهاز</button>\n          <button onClick=\"{{f.phCancel}}\" aria-label=\"إلغاء\" style=\"flex:none;width:56px;min-height:56px;border-radius:14px;border:1px solid rgba(27,36,33,.25);background:#fff;color:#3E4843;display:flex;align-items:center;justify-content:center\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" aria-hidden=\"true\"><use href=\"#i-x\"></use></svg></button>\n        </div>\n        </sc-if>\n        <sc-if value=\"{{f.phOn}}\" hint-placeholder-val=\"{{false}}\">\n        <div style=\"display:flex;align-items:center;gap:12px;border:1px solid rgba(27,36,33,.18);border-radius:14px;background:#fff;padding:8px 12px\">\n          <span style=\"flex:none;width:56px;height:56px;border-radius:10px;background:linear-gradient(135deg,#DCE6DF,#C9D7CD);color:#14563A;display:flex;align-items:center;justify-content:center\"><svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><use href=\"#i-image\"></use></svg></span>\n          <span style=\"flex:1;min-width:0\"><span style=\"display:block;font-size:15px;font-weight:500\">صورة مرفقة</span><span style=\"display:block;font-size:12.5px;color:#5B6660\">{{f.phSrc}} · تُضغط تلقائيًا إلى نحو 60 كيلوبايت</span></span>\n          <button onClick=\"{{f.phOpen}}\" style=\"flex:none;min-height:44px;padding:0 10px;border-radius:12px;border:1px solid rgba(27,36,33,.25);background:#fff;font-size:13.5px;font-weight:500;color:#1B2421\">استبدال</button>\n          <button onClick=\"{{f.phDel}}\" style=\"flex:none;min-height:44px;padding:0 10px;border-radius:12px;border:0;background:#FBEAEA;font-size:13.5px;font-weight:500;color:#9B2C2C\">حذف</button>\n        </div>\n        </sc-if>\n        </div>\n        <sc-if value=\"{{f.isPhView}}\" hint-placeholder-val=\"{{false}}\">\n        <div style=\"display:flex;align-items:center;justify-content:center;min-height:{{f.phH}};border-radius:14px;background:#EEF1EC;overflow:hidden\">\n          <img src=\"{{f.phUrl}}\" alt=\"\" style=\"display:{{f.phShow}};width:100%;max-height:55vh;object-fit:contain\"/>\n          <span style=\"display:{{f.phWait}};font-size:14px;color:#5B6660\">جارٍ فتح الصورة…</span>\n        </div>\n        </sc-if>\n        <sc-if value=\"{{f.isCalc}}\" hint-placeholder-val=\"{{false}}\">\n        <div class=\"cs\" style=\"gap:8px\">\n          <button onMouseDown=\"{{f.keep}}\" onClick=\"{{f.opAdd}}\" aria-label=\"جمع\" style=\"min-height:44px;min-width:56px;padding:0 14px;border-radius:999px;font-size:20px;font-weight:500;background:#FFFFFF;color:#1B2421;border:1px solid rgba(27,36,33,.22)\">+</button>\n          <button onMouseDown=\"{{f.keep}}\" onClick=\"{{f.opSub}}\" aria-label=\"طرح\" style=\"min-height:44px;min-width:56px;padding:0 14px;border-radius:999px;font-size:20px;font-weight:500;background:#FFFFFF;color:#1B2421;border:1px solid rgba(27,36,33,.22)\">−</button>\n          <button onMouseDown=\"{{f.keep}}\" onClick=\"{{f.opMul}}\" aria-label=\"ضرب\" style=\"min-height:44px;min-width:56px;padding:0 14px;border-radius:999px;font-size:20px;font-weight:500;background:#FFFFFF;color:#1B2421;border:1px solid rgba(27,36,33,.22)\">×</button>\n          <button onMouseDown=\"{{f.keep}}\" onClick=\"{{f.opDiv}}\" aria-label=\"قسمة\" style=\"min-height:44px;min-width:56px;padding:0 14px;border-radius:999px;font-size:20px;font-weight:500;background:#FFFFFF;color:#1B2421;border:1px solid rgba(27,36,33,.22)\">÷</button>\n          <button onMouseDown=\"{{f.keep}}\" onClick=\"{{f.opEq}}\" aria-label=\"النتيجة\" style=\"min-height:44px;min-width:56px;padding:0 14px;border-radius:999px;font-size:20px;font-weight:600;background:#14563A;color:#FFFFFF;border:1px solid #14563A\">=</button>\n        </div>\n        </sc-if>\n        <sc-if value=\"{{f.hasHint}}\" hint-placeholder-val=\"{{false}}\"><div style=\"font-size:12.5px;color:#5B6660;line-height:1.6\">{{f.hint}}</div></sc-if>\n      </div>\n      </sc-for>\n\n      <sc-if value=\"{{shHasNote}}\" hint-placeholder-val=\"{{false}}\">\n      <div style=\"background:{{shNoteBg}};color:{{shNoteFg}};border-radius:12px;padding:10px 12px;font-size:13.5px;line-height:1.7\">{{shNote}}</div>\n      </sc-if>\n    </div>\n    <sc-if value=\"{{shHasFooter}}\" hint-placeholder-val=\"{{false}}\">\n    <div style=\"flex:none;display:flex;gap:8px;padding:10px 16px 16px;border-top:1px solid #E1E5DF\">\n      <sc-if value=\"{{shHasFt2}}\" hint-placeholder-val=\"{{false}}\"><button onClick=\"{{shFt2Go}}\" style=\"flex:none;min-height:52px;padding:0 16px;border-radius:14px;border:1px solid rgba(27,36,33,.25);background:#fff;color:#1B2421;font-size:15px;font-weight:600\">{{shFt2Label}}</button></sc-if>\n      <button onClick=\"{{shFtGo}}\" aria-disabled=\"{{shFtDisabled}}\" style=\"flex:1;min-width:0;min-height:52px;border-radius:14px;border:0;background:{{shFtBg}};color:{{shFtFg}};font-size:16px;font-weight:600\">{{shFtLabel}}</button>\n    </div>\n    </sc-if>\n  </div>\n</div>\n</sc-if>\n\n<!-- إشعار قصير -->\n<sc-if value=\"{{toastOn}}\" hint-placeholder-val=\"{{false}}\">\n<div role=\"status\" style=\"position:absolute;left:16px;right:16px;bottom:{{toastBottom}}px;z-index:40;background:#1B2421;color:#fff;border-radius:14px;padding:12px 14px;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:center;box-shadow:0 6px 20px rgba(0,0,0,.25)\">\n  <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#7FD6A6\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex:none\"><use href=\"#i-check\"></use></svg>\n  <span style=\"flex:1;min-width:0\">{{toast}}</span>\n  <sc-if value=\"{{hasUndo}}\" hint-placeholder-val=\"{{false}}\"><button onClick=\"{{doUndo}}\" style=\"flex:none;min-height:44px;min-width:44px;border-radius:10px;border:1px solid rgba(255,255,255,.4);background:transparent;color:#fff;font-size:14px;font-weight:600;padding:0 14px\">تراجع</button></sc-if>\n</div>\n</sc-if>\n\n</div>\n";